import React, { useState, useEffect } from 'react';
import { Calendar, ChevronLeft, ChevronRight, Printer } from 'lucide-react';
import api from '../api';

const Attendance = () => {
    const [estudiantes, setEstudiantes] = useState([]);
    const [trimestre, setTrimestre] = useState(1);
    const [month, setMonth] = useState(new Date().getMonth());
    const [year, setYear] = useState(new Date().getFullYear());
    const [attendanceData, setAttendanceData] = useState({});
    const [attendanceStats, setAttendanceStats] = useState({});

    const [config, setConfig] = useState(null);

    useEffect(() => {
        const configId = localStorage.getItem('activeConfigId');
        if (configId) {
            fetchStudents(configId);
            fetchConfig(configId);
            fetchAttendance(configId);
        }
    }, []);

    const fetchConfig = (id) => {
        api.get(`/config?id=${id}`)
            .then(res => setConfig(res.data))
            .catch(err => console.error(err));
    };

    const fetchStudents = (id) => {
        api.get(`/estudiantes?configId=${id}`)
            .then(res => setEstudiantes(res.data))
            .catch(err => console.error(err));
    };

    const fetchAttendance = (id) => {
        api.get(`/asistencia?configId=${id}`)
            .then(res => {
                const data = {};
                const stats = {};
                res.data.forEach(att => {
                    const date = new Date(att.fecha);
                    // Use UTC values because backend saves as Midnight UTC
                    const y = date.getUTCFullYear();
                    const m = date.getUTCMonth();
                    const d = date.getUTCDate();
                    data[`${att.estudianteId}-${att.trimestre}-${y}-${m}-${d}`] = att.estado;

                    if (!stats[att.estudianteId]) stats[att.estudianteId] = {1: {A:0,F:0,R:0,L:0}, 2: {A:0,F:0,R:0,L:0}, 3: {A:0,F:0,R:0,L:0}};
                    if (att.trimestre && ['A','F','R','L'].includes(att.estado)) {
                        stats[att.estudianteId][att.trimestre][att.estado]++;
                    }
                });
                setAttendanceData(data);
                setAttendanceStats(stats);
            })
            .catch(err => console.error(err));
    };

    const getDaysInMonth = (m, y) => new Date(y, m + 1, 0).getDate();
    const days = Array.from({ length: getDaysInMonth(month, year) }, (_, i) => i + 1);

    const monthNames = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];

    const [customDates, setCustomDates] = useState({});
    
    useEffect(() => {
        if (config?.id !== undefined) {
            const savedDates = localStorage.getItem(`customDates-${config.id}-${trimestre}-${month}-${year}`);
            if(savedDates) {
                try {
                    setCustomDates(JSON.parse(savedDates));
                } catch(e) {
                    setCustomDates({});
                }
            } else {
                setCustomDates({});
            }
        }
    }, [config?.id, trimestre, month, year]);

    const updateCustomDates = (newDates) => {
        setCustomDates(newDates);
        if (config?.id) {
            localStorage.setItem(`customDates-${config.id}-${trimestre}-${month}-${year}`, JSON.stringify(newDates));
        }
    };

    const handleDateChange = (d, val) => {
        updateCustomDates({ ...customDates, [d]: val });
    };

    const handleDateKeyDown = (e, d) => {
        if (e.key === 'Enter') {
            e.preventDefault();
            let val = e.target.value.trim();
            if (!val) {
                const newDates = { ...customDates };
                delete newDates[d];
                updateCustomDates(newDates);
            } else if (/^\d{1,2}$/.test(val)) {
                const dayStr = val.padStart(2, '0');
                const tempMM = String(month + 1).padStart(2, '0');
                const tempYY = String(year).slice(-2);
                const formatted = `${dayStr}/${tempMM}/${tempYY}`;
                updateCustomDates({ ...customDates, [d]: formatted });
            }
            
            const nextInput = document.getElementById(`date-input-${d + 1}`);
            if (nextInput) nextInput.focus();
        }
    };

    const handleDatePaste = (e, d) => {
        e.preventDefault();
        const clipboardData = e.clipboardData || window.clipboardData;
        const pastedText = clipboardData?.getData('text');
        if (!pastedText) return;

        const items = pastedText.split(/\t|\n|\s+/).filter(Boolean);
        const newDates = { ...customDates };
        const tempMM = String(month + 1).padStart(2, '0');
        const tempYY = String(year).slice(-2);
        
        items.forEach((item, idx) => {
            let val = item.trim();
            if (/^\d{1,2}$/.test(val)) {
                const dayStr = val.padStart(2, '0');
                val = `${dayStr}/${tempMM}/${tempYY}`;
            }
            // Save it in the subsequent column slots
            newDates[d + idx] = val;
        });
        
        updateCustomDates(newDates);
    };

    const handleAttendanceChange = (studentId, day, value) => {
        const key = `${studentId}-${trimestre}-${year}-${month}-${day}`;
        const prevVal = attendanceData[key];
        
        // Permitir borrar la celda
        if (value === '') {
            setAttendanceData(prev => ({ ...prev, [key]: null }));
            setAttendanceStats(prev => {
                const newStats = { ...prev };
                if (!newStats[studentId]) return prev;
                if (prevVal && newStats[studentId][trimestre][prevVal] > 0) {
                    newStats[studentId][trimestre][prevVal]--;
                }
                return newStats;
            });
            api.post('/asistencia', { estudianteId: studentId, year, month, day, estado: '', trimestre }).catch(console.error);
            return;
        }
        
        // Tomar siempre el ├║ltimo d├¡gito tecleado (para sobreescribir tipo Excel)
        const val = value.slice(-1).toUpperCase();
        
        // Solo permitir A, F, R, L
        if (['A', 'F', 'R', 'L'].includes(val)) {
            setAttendanceData(prev => ({ ...prev, [key]: val }));
            setAttendanceStats(prev => {
                const newStats = { ...prev };
                if (!newStats[studentId]) newStats[studentId] = {1: {A:0,F:0,R:0,L:0}, 2: {A:0,F:0,R:0,L:0}, 3: {A:0,F:0,R:0,L:0}};
                
                if (prevVal && newStats[studentId][trimestre][prevVal] > 0) {
                    newStats[studentId][trimestre][prevVal]--;
                }
                newStats[studentId][trimestre][val]++;
                return newStats;
            });
            
            api.post('/asistencia', { estudianteId: studentId, year, month, day, estado: val, trimestre }).catch(console.error);
        }
    };

    const handleAttendanceKeyDown = (e, studentIdx, day) => {
        if (e.key === 'Enter' || e.key === 'ArrowDown') {
            e.preventDefault();
            const nextInput = document.getElementById(`att-input-${studentIdx + 1}-${day}`);
            if (nextInput) {
                nextInput.focus();
                nextInput.select();
            }
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            const prevInput = document.getElementById(`att-input-${studentIdx - 1}-${day}`);
            if (prevInput) {
                prevInput.focus();
                prevInput.select();
            }
        } else if (e.key === 'ArrowRight') {
            e.preventDefault();
            const nextInput = document.getElementById(`att-input-${studentIdx}-${day + 1}`);
            if (nextInput) {
                nextInput.focus();
                nextInput.select(); // Jump exactly next cell same row
            }
        } else if (e.key === 'ArrowLeft') {
            e.preventDefault();
            const prevInput = document.getElementById(`att-input-${studentIdx}-${day - 1}`);
            if (prevInput) {
                prevInput.focus();
                prevInput.select();
            }
        }
    };

    return (
        <div className="p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-6">
                <div className="space-y-3 w-full md:w-auto">
                    <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight flex items-center gap-3">
                        <div className="w-2 h-10 bg-purple-600 rounded-full"></div>
                        Control de Asistencia
                    </h2>

                    {config && (
                        <div className="flex flex-wrap gap-3 text-[10px] font-bold uppercase tracking-wider">
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400 font-medium">Maestro:</span>
                                <span className="text-slate-700">{config.maestro || '---'}</span>
                            </div>
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400 font-medium">Grado:</span>
                                <span className="text-slate-700">{config.curso || '---'}</span>
                            </div>
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400 font-medium">Asignatura:</span>
                                <span className="text-slate-700">{config.area || '---'}</span>
                            </div>
                            <div className="flex bg-slate-100 rounded-md p-0.5 border border-slate-200">
                                {[1, 2, 3].map(t => (
                                    <button
                                        key={t}
                                        onClick={() => setTrimestre(t)}
                                        className={`px-3 py-1 text-[9px] font-black rounded transition ${trimestre === t ? 'bg-purple-600 text-white shadow-sm' : 'text-slate-500 hover:bg-white'}`}
                                    >
                                        {t}┬║ TRI
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
                <div className="flex items-center space-x-4 w-full md:w-auto justify-between md:justify-end">
                    <div className="flex items-center bg-white border border-slate-200 rounded-xl px-3 py-2 shadow-sm">
                        <button onClick={() => setMonth(m => m === 0 ? 11 : m - 1)} className="p-1 hover:bg-slate-100 rounded-lg transition-colors text-slate-500"><ChevronLeft size={18} /></button>
                        <span className="w-28 text-center font-black text-xs uppercase tracking-widest text-slate-700">{monthNames[month]}</span>
                        <button onClick={() => setMonth(m => m === 11 ? 0 : m + 1)} className="p-1 hover:bg-slate-100 rounded-lg transition-colors text-slate-500"><ChevronRight size={18} /></button>
                    </div>
                    <button className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-bold flex items-center space-x-3 hover:bg-black transition shadow-lg shadow-slate-200 hover:-translate-y-1 active:scale-95">
                        <Printer size={18} />
                        <span className="text-xs uppercase tracking-wider">Exportar PDF</span>
                    </button>
                </div>
            </div>

            <div className="bg-white rounded-xl shadow-2xl border border-slate-200 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full border-collapse text-[10px]">
                        <thead>
                            <tr className="bg-slate-50">
                                <th rowSpan="2" className="border border-slate-300 w-8 p-1">N┬║</th>
                                <th rowSpan="2" className="border border-slate-300 w-64 p-2 text-left uppercase">N├│mina de Estudiantes</th>
                                <th colSpan={days.length} className="border border-slate-300 py-1 bg-excel-purple/10 text-excel-purple font-bold uppercase tracking-widest">
                                    Registro Diario de Asistencia
                                </th>
                                <th colSpan="4" className="border border-slate-300 p-1 bg-yellow-50">RESUMEN</th>
                            </tr>
                            <tr className="bg-slate-50 h-24">
                                {days.map(d => {
                                    const displayDate = customDates[d] !== undefined ? customDates[d] : '';
                                    
                                    return (
                                        <th key={d} className="border border-slate-300 w-6 relative overflow-visible">
                                            <div className="absolute inset-0 flex items-center justify-center">
                                                <input
                                                    id={`date-input-${d}`} 
                                                    className="transform -rotate-90 origin-center whitespace-nowrap text-[12px] font-black text-slate-700 bg-transparent outline-none w-[60px] text-center hover:bg-slate-100 focus:bg-purple-100 focus:text-purple-700 rounded-sm cursor-text transition-colors"
                                                    value={displayDate}
                                                    onChange={e => handleDateChange(d, e.target.value)}
                                                    onKeyDown={e => handleDateKeyDown(e, d)}
                                                    onPaste={e => handleDatePaste(e, d)}
                                                    title="Escriba el d├¡a y presione Enter (Ej. 15)"
                                                />
                                            </div>
                                        </th>
                                    );
                                })}
                                <th className="border border-slate-300 w-8 bg-green-50 text-green-700">A</th>
                                <th className="border border-slate-300 w-8 bg-red-50 text-red-700">F</th>
                                <th className="border border-slate-300 w-8 bg-blue-50 text-blue-700">R</th>
                                <th className="border border-slate-300 w-8 bg-orange-50 text-orange-700">L</th>
                            </tr>
                        </thead>
                        <tbody>
                            {estudiantes.map((e, idx) => {
                                const stats = attendanceStats[e.id]?.[trimestre] || {A:0, F:0, R:0, L:0};
                                const { A: asist, F: falt, R: retr, L: lice } = stats;

                                return (
                                    <tr key={e.id} className="hover:bg-slate-50 border-b border-slate-100">
                                        <td className="border border-slate-300 text-center font-bold text-slate-400 py-1">{idx + 1}</td>
                                        <td className="border border-slate-300 px-2 font-bold text-slate-700 uppercase">{e.apellidos} {e.nombres}</td>
                                        {days.map(d => {
                                            const status = attendanceData[`${e.id}-${trimestre}-${year}-${month}-${d}`];
                                            return (
                                                <td
                                                    key={d}
                                                    className={`border border-slate-300 transition-colors p-0 m-0 ${status === 'A' ? 'bg-green-100 text-green-700' :
                                                        status === 'F' ? 'bg-red-100 text-red-700' :
                                                            status === 'R' ? 'bg-blue-100 text-blue-700' :
                                                                status === 'L' ? 'bg-orange-100 text-orange-700' : ''
                                                        }`}
                                                >
                                                    <input
                                                        id={`att-input-${idx}-${d}`}
                                                        className="w-full h-full min-h-[22px] text-center bg-transparent outline-none uppercase font-bold cursor-text focus:shadow-[inset_0_0_0_2px_#9333ea] focus:bg-white"
                                                        value={status || ''}
                                                        onChange={ev => handleAttendanceChange(e.id, d, ev.target.value)}
                                                        onKeyDown={ev => handleAttendanceKeyDown(ev, idx, d)}
                                                    />
                                                </td>
                                            );
                                        })}
                                        <td className="border border-slate-300 text-center bg-green-50/30 font-bold">{asist || ''}</td>
                                        <td className="border border-slate-300 text-center bg-red-50/30 font-bold text-red-600">{falt || ''}</td>
                                        <td className="border border-slate-300 text-center bg-blue-50/30 font-bold">{retr || ''}</td>
                                        <td className="border border-slate-300 text-center bg-orange-50/30 font-bold">{lice || ''}</td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
};

export default Attendance;

