import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { PlusCircle, GraduationCap, BookOpen, User, MapPin, School, Calendar, ChevronRight, RefreshCw, Trash2 } from 'lucide-react';
import api from '../api';

const GRADOS = [
    '1RO SEC',
    '2DO SEC',
    '3RO SEC',
    '4TO SEC',
    '5TO SEC',
    '6TO SEC'
];

const AREAS = [
    'MATEM├üTICAS',
    'CIENCIAS SOCIALES',
    'COSMOVISIONES FILOSOF├ìA SICOLOG├ìA',
    'ARTES PL├üSTICAS Y VISUALES',
    'BIOLOG├ìA',
    'QU├ìMICA',
    'F├ìSICA',
    'M├ÜSICA',
    'EDUCACI├ôN F├ìSICA Y DEPORTES',
    'T├ëCNICA TECNOLOG├ìA GENERAL',
    'LENGUA EXTRANJERA',
    'LENGUA CASTELLANA ORIGINARIA'
];

const InputField = ({ label, icon: Icon, value, onChange, placeholder, type = "text" }) => (
    <div className="space-y-1 group">
        <label className="text-[11px] font-bold text-slate-500 flex items-center gap-1 group-focus-within:text-purple-600 transition-colors uppercase">
            <Icon size={12} className="text-purple-400 group-focus-within:text-purple-600" />
            {label}
        </label>
        <input
            type={type}
            className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-purple-100 focus:border-purple-500 outline-none transition-all duration-300 text-slate-700 font-semibold shadow-sm text-sm"
            value={value || ''}
            onChange={onChange}
            placeholder={placeholder}
        />
    </div>
);

const SelectField = ({ label, icon: Icon, value, onChange, options }) => (
    <div className="space-y-1 group">
        <label className="text-[11px] font-bold text-slate-500 flex items-center gap-1 group-focus-within:text-purple-600 transition-colors uppercase">
            <Icon size={12} className="text-purple-400 group-focus-within:text-purple-600" />
            {label}
        </label>
        <div className="relative">
            <select
                className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-purple-100 focus:border-purple-500 outline-none transition-all duration-300 text-slate-700 font-bold appearance-none cursor-pointer shadow-sm text-sm"
                value={value || ''}
                onChange={onChange}
            >
                <option value="">Seleccione una opci├│n</option>
                {options.map(opt => (
                    <option key={opt} value={opt}>{opt}</option>
                ))}
            </select>
            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-purple-400">
                <ChevronRight size={14} className="rotate-90" />
            </div>
        </div>
    </div>
);

const Config = () => {
    const [config, setConfig] = useState({
        distrito: 'Shinahota',
        unidadEducativa: 'San Luis',
        nivel: 'secundaria',
        maestro: 'alfredo casaya',
        area: 'MATEM├üTICAS',
        gestion: '2026',
        curso: '1RO SEC'
    });
    const [allConfigs, setAllConfigs] = useState([]);
    const [showModal, setShowModal] = useState(false);

    const fetchAllConfigs = () => {
        api.get('/configs')
            .then(res => {
                setAllConfigs(Array.isArray(res.data) ? res.data : []);
            })
            .catch(err => {
                console.error('Error fetching configs:', err);
                setAllConfigs([]);
            });
    };

    useEffect(() => {
        fetchAllConfigs();
    }, []);

    useEffect(() => {
        const lastConfigId = localStorage.getItem('activeConfigId');
        if (lastConfigId) {
            api.get(`/config?id=${lastConfigId}`)
                .then(res => {
                    if (res.data && res.data.id) {
                        setConfig(res.data);
                    }
                })
                .catch(err => console.error('Error fetching initial config:', err));
        }
    }, []);

    const handleChange = (field, value) => {
        setConfig(prev => {
            const updated = { ...prev, [field]: value };

            if (field === 'curso' || field === 'area') {
                const existing = allConfigs.find(c => c.curso === updated.curso && c.area === updated.area);
                if (existing) {
                    localStorage.setItem('activeConfigId', existing.id);
                    return { ...existing };
                } else {
                    const { id, ...rest } = updated;
                    return rest;
                }
            }
            return updated;
        });
    };

    const handleSaveGeneral = () => {
        const { distrito, unidadEducativa, nivel, maestro, gestion } = config;
        if (!distrito || !unidadEducativa || !nivel || !maestro || !gestion) {
            alert('Por favor complete todos los datos generales antes de guardar.');
            return;
        }

        api.put(`/config/general`, config)
            .then(res => {
                alert('┬íDATOS GENERALES ACTUALIZADOS CON ├ëXITO!');
                fetchAllConfigs();
            })
            .catch(err => {
                console.error('Error saving general data:', err);
                const msg = err.response?.data?.error || err.message;
                alert(`Error al guardar datos generales: ${msg}`);
            });
    };

    const handleSubmit = (e) => {
        if (e) e.preventDefault();

        if (!config.curso || !config.area) {
            alert('Debe seleccionar Grado y ├ürea.');
            return;
        }

        api.post(`/config`, config)
            .then(res => {
                if (res.data && res.data.id) {
                    setConfig(res.data);
                    localStorage.setItem('activeConfigId', res.data.id);
                    fetchAllConfigs();
                    setShowModal(false);
                    // Retirado el setTimeout con alert para evitar congelamiento de la app
                }
            })
            .catch(err => {
                console.error('Error creating course:', err);
                const msg = err.response?.data?.error || err.message;
                alert(`No se pudo guardar el curso: ${msg}`);
            });
    };

    const handleSelectConfig = (id) => {
        api.get(`/config?id=${id}`)
            .then(res => {
                if (res.data && res.data.id) {
                    setConfig(res.data);
                    localStorage.setItem('activeConfigId', res.data.id);
                }
            })
            .catch(err => console.error('Error selecting config:', err));
    };

    const handleDelete = (e, id, curso, area) => {
        e.stopPropagation();
        const firstConfirm = window.confirm(`┬┐Est├í seguro de que desea eliminar el curso: ${curso} - ${area}?\n\nEsta acci├│n borrar├í el registro y TODOS los datos asociados.`);
        if (firstConfirm) {
            const secondConfirm = window.confirm(`┬íADVERTENCIA CR├ìTICA!\n\nEst├í a punto de borrar definitivamente este curso. Esta acci├│n es IRREVERSIBLE.\n\n┬┐Desea proceder con la eliminaci├│n?`);
            if (secondConfirm) {
                api.delete(`/config/${id}`)
                    .then(() => {
                        alert('Curso eliminado exitosamente.');
                        fetchAllConfigs();
                        if (config.id === id) {
                            handleNew();
                        }
                    })
                    .catch(err => {
                        console.error('Error deleting course:', err);
                        alert(`No se pudo eliminar el curso: ${err.message}`);
                    });
            }
        }
    };

    const handleNew = () => {
        setConfig(curr => ({
            ...curr,
            id: undefined,
            area: '',
            curso: ''
        }));
        localStorage.removeItem('activeConfigId');
    };

    const getShortLabel = (curso, area) => {
        if (!curso) return "...";
        const numPart = curso.split(' ')[0];
        const number = numPart.replace(/[^0-9]/g, '');
        const suffix = numPart.replace(/[0-9]/g, '').toLowerCase();
        const areaPart = area ? area.substring(0, 3).toUpperCase() : '';
        return `${number}${suffix} ${areaPart}`;
    };

    return (
        <div className="max-w-7xl mx-auto py-4 px-4 space-y-6">
            {/* Section 1: Education Unit Data (Full Width Dashboard Style) */}
            <div className="bg-white rounded-[2.5rem] shadow-xl shadow-purple-100/30 overflow-hidden border border-slate-100 transition-all duration-500">
                <div className="bg-gradient-to-r from-purple-600 via-purple-700 to-indigo-800 p-4 text-white flex flex-col md:flex-row items-center justify-between gap-4">
                    <div className="flex items-center gap-3">
                        <div className="p-2.5 bg-white/10 rounded-2xl backdrop-blur-md border border-white/10">
                            <School size={24} className="text-purple-100" />
                        </div>
                        <div>
                            <h2 className="text-lg font-black tracking-tight uppercase leading-none">Configuraci├│n General</h2>
                            <p className="text-[10px] text-purple-200 font-bold uppercase tracking-widest mt-1">Gesti├│n Acad├®mica {config.gestion || '2026'}</p>
                        </div>
                    </div>

                    <div className="flex items-center gap-3">
                        <button
                            onClick={handleSaveGeneral}
                            className="bg-emerald-500 text-white px-5 py-2.5 rounded-xl font-black text-xs flex items-center gap-2 hover:bg-emerald-600 transition-all shadow-lg shadow-emerald-500/20 active:scale-95"
                        >
                            <RefreshCw size={14} />
                            GUARDAR CAMBIOS
                        </button>
                        <button
                            onClick={() => setShowModal(true)}
                            className="bg-white/10 text-white px-5 py-2.5 rounded-xl font-black text-xs flex items-center gap-2 hover:bg-white/20 transition-all border border-white/20 active:scale-95 group"
                        >
                            <PlusCircle size={16} className="group-hover:rotate-90 transition-transform" />
                            CREAR CURSO
                        </button>
                    </div>
                </div>

                <div className="p-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6 bg-slate-50/30">
                    <InputField label="Distrito Educativo" icon={MapPin} value={config.distrito} onChange={(e) => handleChange('distrito', e.target.value)} placeholder="Ej. Distrito" />
                    <InputField label="Unidad Educativa" icon={School} value={config.unidadEducativa} onChange={(e) => handleChange('unidadEducativa', e.target.value)} placeholder="Ej. San Luis" />
                    <InputField label="Nivel" icon={GraduationCap} value={config.nivel} onChange={(e) => handleChange('nivel', e.target.value)} placeholder="Ej. Secundaria" />
                    <InputField label="Maestro(a)" icon={User} value={config.maestro} onChange={(e) => handleChange('maestro', e.target.value)} placeholder="Nombre Maestro" />
                    <InputField label="Gesti├│n" icon={Calendar} value={config.gestion} onChange={(e) => handleChange('gestion', e.target.value)} placeholder="2026" />
                </div>
            </div>

            {/* Section 2: Courses Dashboard Grid */}
            <div className="bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 border border-slate-100 p-8">
                <div className="flex flex-col md:flex-row items-center justify-between mb-8 gap-4 border-b border-slate-50 pb-6">
                    <div className="flex items-center gap-5">
                        <div className="p-3 bg-purple-100 rounded-2xl text-purple-600 shadow-inner">
                            <GraduationCap size={28} />
                        </div>
                        <div>
                            <h3 className="text-slate-800 font-black text-2xl flex items-center gap-3">
                                CURSOS REGISTRADOS
                                <span className="bg-purple-600 text-white px-3 py-1 rounded-full text-xs font-black">
                                    {allConfigs.length}
                                </span>
                            </h3>
                            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1 italic">Haga clic en una tarjeta para seleccionarla</p>
                        </div>
                    </div>
                    <button 
                        onClick={handleNew}
                        className="text-xs font-black bg-slate-50 text-slate-500 px-6 py-3 rounded-2xl hover:bg-purple-50 hover:text-purple-600 transition-all flex items-center gap-2 border border-slate-100 hover:border-purple-200"
                    >
                        <RefreshCw size={14} />
                        LIMPIAR / NUEVO
                    </button>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-5 gap-6">
                    {allConfigs.map((c) => (
                        <div
                            key={c.id}
                            onClick={() => handleSelectConfig(c.id)}
                            className={`
                                group relative p-6 rounded-3xl cursor-pointer transition-all duration-300 border-2
                                ${config.id === c.id 
                                    ? 'bg-gradient-to-br from-purple-600 to-indigo-700 border-transparent shadow-2xl shadow-purple-300 scale-[1.03]' 
                                    : 'bg-white border-slate-50 hover:border-purple-200 shadow-sm hover:shadow-xl hover:shadow-purple-100/50'}
                            `}
                        >
                            <div className="flex items-center justify-between mb-4">
                                <div className={`p-2.5 rounded-xl transition-colors ${config.id === c.id ? 'bg-white/20 text-white' : 'bg-purple-50 text-purple-600'}`}>
                                    <BookOpen size={22} />
                                </div>
                                <button
                                    onClick={(e) => handleDelete(e, c.id, c.curso, c.area)}
                                    className={`p-2 rounded-xl transition-all ${config.id === c.id ? 'hover:bg-red-500 text-white/80' : 'hover:bg-red-50 text-slate-300 hover:text-red-500'}`}
                                >
                                    <Trash2 size={18} />
                                </button>
                            </div>

                            <div className="space-y-1">
                                <p className={`text-xl font-black leading-tight tracking-tight ${config.id === c.id ? 'text-white' : 'text-slate-800'}`}>
                                    {c.curso}
                                </p>
                                <p className={`text-[11px] font-bold uppercase tracking-widest ${config.id === c.id ? 'text-purple-100' : 'text-slate-400'} truncate`}>
                                    {c.area}
                                </p>
                            </div>

                            {config.id === c.id && (
                                <div className="absolute -bottom-2 -right-2 opacity-10 rotate-12">
                                    <GraduationCap size={80} />
                                </div>
                            )}

                            <div className={`absolute top-0 left-1/2 -translate-x-1/2 w-12 h-1 rounded-b-full transition-all duration-500 ${config.id === c.id ? 'bg-white' : 'bg-transparent'}`}></div>
                        </div>
                    ))}

                    {allConfigs.length === 0 && (
                        <div className="col-span-full py-16 text-center bg-slate-50 rounded-[2.5rem] border-2 border-dashed border-slate-200 group hover:border-purple-300 transition-colors">
                            <GraduationCap size={48} className="mx-auto text-slate-300 mb-4 group-hover:text-purple-300 transition-colors" />
                            <p className="text-slate-400 font-black text-lg">No hay cursos registrados a├║n.</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Modal for Course Creation */}
            {showModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setShowModal(false)}></div>
                    <div className="relative bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden animate-in fade-in zoom-in duration-200 border border-slate-100">
                        <div className="bg-gradient-to-r from-purple-600 to-indigo-600 p-5 text-white flex justify-between items-center">
                            <h3 className="font-black text-sm uppercase tracking-widest flex items-center gap-2">
                                <PlusCircle size={18} />
                                Nuevo Curso / Asignatura
                            </h3>
                            <button onClick={() => setShowModal(false)} className="text-white/70 hover:text-white">
                                <ChevronRight className="rotate-180" size={24} />
                            </button>
                        </div>
                        <div className="p-6 space-y-6">
                            <div className="space-y-4">
                                <SelectField label="Grado / Curso" icon={GraduationCap} value={config.curso} onChange={(e) => handleChange('curso', e.target.value)} options={GRADOS} />
                                <SelectField label="├ürea / Asignatura" icon={BookOpen} value={config.area} onChange={(e) => handleChange('area', e.target.value)} options={AREAS} />
                            </div>
                            <div className="flex justify-end gap-3 pt-4 border-t border-slate-50">
                                <button onClick={() => setShowModal(false)} className="px-4 py-2 rounded-xl text-xs font-bold text-slate-500 hover:bg-slate-100">CANCELAR</button>
                                <button onClick={handleSubmit} className="bg-purple-600 text-white px-6 py-2 rounded-xl font-black text-xs flex items-center gap-2 hover:bg-purple-700 shadow-lg shadow-purple-100">
                                    <PlusCircle size={14} />
                                    GUARDAR CURSO
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Config;

