import React, { useState, useEffect } from 'react';
import { GraduationCap, Printer, Info } from 'lucide-react';
import api from '../api';

const Grades = () => {
    const [estudiantes, setEstudiantes] = useState([]);
    const [trimestre, setTrimestre] = useState(1);
    const [grades, setGrades] = useState({});
    const [headers, setHeaders] = useState({});
    const [config, setConfig] = useState(null);

    useEffect(() => {
        const configId = localStorage.getItem('activeConfigId');
        if (configId) {
            fetchStudents(configId);
            fetchConfig(configId);
            fetchGrades(configId, trimestre);
            loadHeaders(configId, trimestre);
        }
    }, []);

    useEffect(() => {
        const configId = localStorage.getItem('activeConfigId');
        if (configId) {
            fetchGrades(configId, trimestre);
            loadHeaders(configId, trimestre);
        }
    }, [trimestre]);

    const loadHeaders = (configId, trim) => {
        const savedHeaders = localStorage.getItem(`gradesHeaders-${configId}-${trim}`);
        if(savedHeaders) {
            try {
                setHeaders(JSON.parse(savedHeaders));
            } catch(e) {
                setHeaders({});
            }
        } else {
            setHeaders({});
        }
    };

    const updateHeader = (key, value) => {
        const newHeaders = { ...headers, [key]: value };
        setHeaders(newHeaders);
        if (config?.id) {
            localStorage.setItem(`gradesHeaders-${config.id}-${trimestre}`, JSON.stringify(newHeaders));
        }
    };

    const fetchGrades = (configId, trim) => {
        api.get(`/notas?configId=${configId}&trimestre=${trim}`)
            .then(res => {
                const newGrades = {};
                res.data.forEach(nota => {
                    newGrades[`${nota.estudianteId}-ser_1`] = nota.ser_1 || 0;
                    newGrades[`${nota.estudianteId}-ser_2`] = nota.ser_2 || 0;
                    newGrades[`${nota.estudianteId}-sab_1`] = nota.saber_1 || 0;
                    newGrades[`${nota.estudianteId}-sab_2`] = nota.saber_2 || 0;
                    newGrades[`${nota.estudianteId}-sab_3`] = nota.saber_3 || 0;
                    newGrades[`${nota.estudianteId}-sab_4`] = nota.saber_4 || 0;
                    newGrades[`${nota.estudianteId}-sab_5`] = nota.saber_5 || 0;
                    newGrades[`${nota.estudianteId}-sab_6`] = nota.saber_6 || 0;
                    newGrades[`${nota.estudianteId}-hac_1`] = nota.hacer_1 || 0;
                    newGrades[`${nota.estudianteId}-hac_2`] = nota.hacer_2 || 0;
                    newGrades[`${nota.estudianteId}-hac_3`] = nota.hacer_3 || 0;
                    newGrades[`${nota.estudianteId}-hac_4`] = nota.hacer_4 || 0;
                    newGrades[`${nota.estudianteId}-hac_5`] = nota.hacer_5 || 0;
                    newGrades[`${nota.estudianteId}-hac_6`] = nota.hacer_6 || 0;
                    newGrades[`${nota.estudianteId}-auto_ser`] = nota.auto_ser || 0;
                });
                setGrades(newGrades);
            })
            .catch(err => console.error(err));
    };

    const fetchConfig = (id) => {
        api.get(`/config?id=${id}`)
            .then(res => setConfig(res.data))
            .catch(err => console.error(err));
    };

    const fetchStudents = (id) => {
        api.get(`/estudiantes?configId=${id}`)
            .then(res => setEstudiantes(res.data))
            .catch(err => console.error(err));
    };

    const handleGradeChange = (studentId, field, value) => {
        setGrades({
            ...grades,
            [`${studentId}-${field}`]: value === "" ? "" : (parseFloat(value) || 0)
        });
    };

    const getAverageForGroup = (studentId, prefix, count) => {
        let sum = 0;
        let filledCount = 0;
        for (let i = 1; i <= count; i++) {
            const val = grades[`${studentId}-${prefix}_${i}`];
            if (val !== undefined && val !== '' && val > 0) {
                sum += parseFloat(val);
                filledCount++;
            }
        }
        if (filledCount === 0) return 0;
        return Math.round(sum / filledCount);
    };

    const handleSaveGrade = (studentId) => {
        const promSer = getAverageForGroup(studentId, 'ser', 2);
        const promSab = getAverageForGroup(studentId, 'sab', 6);
        const promHac = getAverageForGroup(studentId, 'hac', 6);
        const autoSer = parseFloat(grades[`${studentId}-auto_ser`]) || 0;

        const notaTrimestre = Math.round(promSer + promSab + promHac + autoSer);

        const data = {
            estudianteId: studentId,
            trimestre,
            ser_1: parseFloat(grades[`${studentId}-ser_1`]) || 0,
            ser_2: parseFloat(grades[`${studentId}-ser_2`]) || 0,
            saber_1: parseFloat(grades[`${studentId}-sab_1`]) || 0,
            saber_2: parseFloat(grades[`${studentId}-sab_2`]) || 0,
            saber_3: parseFloat(grades[`${studentId}-sab_3`]) || 0,
            saber_4: parseFloat(grades[`${studentId}-sab_4`]) || 0,
            saber_5: parseFloat(grades[`${studentId}-sab_5`]) || 0,
            saber_6: parseFloat(grades[`${studentId}-sab_6`]) || 0,
            hacer_1: parseFloat(grades[`${studentId}-hac_1`]) || 0,
            hacer_2: parseFloat(grades[`${studentId}-hac_2`]) || 0,
            hacer_3: parseFloat(grades[`${studentId}-hac_3`]) || 0,
            hacer_4: parseFloat(grades[`${studentId}-hac_4`]) || 0,
            hacer_5: parseFloat(grades[`${studentId}-hac_5`]) || 0,
            hacer_6: parseFloat(grades[`${studentId}-hac_6`]) || 0,
            auto_ser: autoSer,
            auto_decidir: autoSer,
            notaTrimestre
        };
        api.post('/notas', data).catch(console.error);
    };

    const getRango = (total) => {
        if (!total || total === 0) return '';
        if (total < 51) return 'ED';
        if (total >= 51 && total <= 67) return 'DA';
        if (total >= 68 && total <= 84) return 'DO';
        if (total >= 85) return 'DP';
        return '';
    };

    return (
        <div className="p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-6">
                <div className="space-y-3 w-full md:w-auto">
                    <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight flex items-center gap-3">
                        <div className="w-2 h-10 bg-[#e05634] rounded-full"></div>
                        Registro de Valoraci├│n
                    </h2>

                    {config && (
                        <div className="flex flex-wrap gap-3 text-[10px] font-bold uppercase tracking-wider">
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400 font-medium">Maestro:</span>
                                <span className="text-slate-700">{config.maestro || '---'}</span>
                            </div>
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400 font-medium">Grado:</span>
                                <span className="text-slate-700">{config.curso || '---'}</span>
                            </div>
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400 font-medium">Asignatura:</span>
                                <span className="text-slate-700">{config.area || '---'}</span>
                            </div>
                            <div className="flex bg-white rounded-md p-0.5 border border-slate-200">
                                {[1, 2, 3].map(t => (
                                    <button
                                        key={t}
                                        onClick={() => setTrimestre(t)}
                                        className={`px-4 py-1.5 text-[9px] font-black rounded transition ${trimestre === t ? 'bg-[#c62828] text-white shadow-sm' : 'text-slate-500 hover:bg-slate-50'}`}
                                    >
                                        {t}┬║ TRI
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
                <button className="bg-slate-900 text-white px-6 py-3.5 rounded-2xl font-bold flex items-center space-x-3 hover:bg-black transition shadow-lg shadow-slate-200 hover:-translate-y-1 active:scale-95 no-print">
                    <Printer size={18} />
                    <span className="text-xs uppercase tracking-wider">Imprimir Cuadro</span>
                </button>
            </div>

            <div className="bg-white shadow-xl border border-black overflow-hidden print-grades-container">
                <div className="overflow-x-auto">
                    {/* Estilos espec├¡ficos para replicar la imagen de manera exacta */}
                    <style>{`
                        .tabla-valoracion {
                            border-collapse: collapse;
                            width: 100%;
                            font-family: Arial, sans-serif;
                            font-size: 11px;
                        }
                        .tabla-valoracion th, .tabla-valoracion td {
                            border: 1px solid black;
                            padding: 0;
                            text-align: center;
                            vertical-align: middle;
                        }
                        .tabla-valoracion input {
                            width: 100%;
                            height: 100%;
                            border: none;
                            text-align: center;
                            font-family: Arial, sans-serif;
                            font-size: 12px;
                            background: transparent;
                            outline: none;
                            min-height: 20px;
                        }
                        .vertical-header-container {
                            height: 140px;
                            position: relative;
                            width: 22px;
                        }
                        .vertical-header-input {
                            writing-mode: vertical-rl;
                            transform: rotate(180deg);
                            white-space: nowrap;
                            text-align: left;
                            padding-top: 5px;
                            width: 100%;
                            height: 100%;
                            border: none;
                            background: transparent;
                            font-size: 10px;
                            outline: none;
                            font-family: inherit;
                        }
                        .bg-promedio-orange { background-color: #fce4d6; }
                        .bg-autoeval-peach { background-color: #f8cbad; }
                        .bg-promedio-blue { background-color: #d9e1f2; }
                        .bg-rango-peach { background-color: #fce4d6; }
                        .bg-final-gray { background-color: #ededed; }
                        .text-red-header { color: #c00000; font-weight: bold; }
                        .text-purple-header { color: #7030a0; font-weight: bold; font-size: 12px; }

                        .thick-left { border-left: 2px solid black !important; }
                        .thick-right { border-right: 2px solid black !important; }
                    `}</style>
                    <table className="tabla-valoracion" translate="no">
                        <thead>
                            {/* Fila 1 */}
