                {/* App Controls */}
                <div className="schedule-app-controls no-print">
                    <div className="schedule-week-navigator">
                        <button className="schedule-btn schedule-btn-nav" onClick={navigatePrev}>ÔùÇ Semana Anterior</button>
                        <div style={{display:'flex', alignItems:'center', gap:'10px'}}>
                            <input 
                                type="date" 
                                title="Buscar una fecha" 
                                value={getWeekStartStr()} 
                                onChange={handleDateSearch}
                            />
                            <button className="schedule-btn schedule-btn-nav" onClick={navigateToday}>­ƒôà Hoy</button>
                        </div>
                        <button className="schedule-btn schedule-btn-nav" onClick={navigateNext}>Semana Siguiente ÔûÂ</button>
                    </div>
                    <div className="schedule-current-week-display">{currentWeekDisplay}</div>
                </div>

                {/* Cabecera */}
                <div className="schedule-header">
                    <h1 className="schedule-title">AGENDA Y HORARIO 2026</h1>
                    <div className="schedule-institution-info">
                        DISTRITO: {config?.distrito || 'Shinahota'} ÔÇó UNIDAD EDUCATIVA: {config?.unidadEducativa || '"San Luis"'}
                    </div>

                    <div className="schedule-details-grid">
                        <div className="schedule-detail-item">
                            <span className="schedule-detail-label">Nivel</span>
                            <span className="schedule-detail-value">{config?.nivel || 'Educaci├│n Regular'}</span>
                        </div>
                        <div className="schedule-detail-item">
                            <span className="schedule-detail-label">Profesor</span>
                            <span className="schedule-detail-value">{config?.maestro || 'Alfredo Casaya Almanza'}</span>
                        </div>
                        <div className="schedule-detail-item">
                            <span className="schedule-detail-label">Formato</span>
                            <span className="schedule-detail-value">Carta Horizontal</span>
                        </div>
                        <div className="schedule-detail-item">
                            <span className="schedule-detail-label">Mes</span>
                            <span className="schedule-detail-value">{monthsNames[monday.getMonth()]}</span>
                        </div>
                        <div className="schedule-detail-item">
                            <span className="schedule-detail-label">A├▒o</span>
                            <span className="schedule-detail-value">{config?.gestion || '2026'}</span>
                        </div>
                    </div>
                </div>

                {/* Tabla de horario interactivo */}
                <div className="schedule-table-container">
                    <table className="schedule-table">
                        <thead>
                            <tr>
                                <th>PER.</th>
                                <th>HORAS</th>
                                {days.map((d, idx) => (
                                    <th className="schedule-day-cell" key={idx}>
                                        {dayNames[idx]} {d.getDate()}
                                    </th>
                                ))}
                            </tr>
