                            </h2>
                            <span className="schedule-close-btn" onClick={closeModal}>&times;</span>
                        </div>
                        <div className="schedule-modal-body">
                            <div className="schedule-modal-section">
                                <h3>­ƒôØ Notas y Tareas de la Semana</h3>
                                <textarea 
                                    placeholder="Escribe aqu├¡ las tareas, observaciones o apuntes r├ípidos para esta materia en la semana seleccionada..."
                                    value={modalNotes}
                                    onChange={handleNotesChange}
                                ></textarea>
                                <div style={{textAlign: 'right', marginTop: '8px', minHeight: '24px'}}>
                                    <span style={{color: saveStatus.color, marginRight: '10px', fontWeight: '600', fontSize: '0.9rem', opacity: saveStatus.show ? 1 : 0, transition: 'opacity 0.3s'}}>
                                        {saveStatus.text}
                                    </span>
                                    <button className="schedule-btn schedule-btn-primary" onClick={() => saveNotes()}>­ƒÆ¥ Guardar Notas</button>
                                </div>
                            </div>

                            <div className="schedule-modal-section">
                                <h3>­ƒôü Gesti├│n de Documentos</h3>
                                <p style={{fontSize: '0.85rem', color: '#64748b', marginBottom: '10px'}}>Adjunta cualquier tipo de archivo (Word, Excel, PDF, OpenDocument, im├ígenes, etc.). Los archivos se guardan en la agenda de forma segura.</p>
                                <div className="schedule-file-upload-wrapper">
                                    <input type="file" ref={fileInputRef} style={{display: 'none'}} multiple onChange={handleFileUpload} />
                                    <button className="schedule-btn schedule-btn-secondary" onClick={() => fileInputRef.current?.click()}>­ƒôÑ Subir Archivos</button>
                                </div>

                                <div className="schedule-file-list">
                                    {modalFiles.length === 0 ? (
                                        <p style={{color: '#64748b', fontSize: '0.9rem', fontStyle: 'italic', padding: '10px 0'}}>
                                            No hay documentos guardados para esta materia en esta semana.
                                        </p>
                                    ) : (
                                        modalFiles.map(f => {
                                            const sizeMb = (f.fileSize / (1024*1024)).toFixed(2);
                                            let icon = "­ƒôä";
                                            if(f.fileType.includes("image")) icon = "­ƒû╝´©Å";
                                            else if(f.fileType.includes("pdf")) icon = "­ƒôò";
                                            else if(f.fileType.includes("spreadsheet") || f.fileName.endsWith(".xls") || f.fileName.endsWith(".xlsx") || f.fileName.endsWith(".ods")) icon = "­ƒôè";
                                            else if(f.fileType.includes("word") || f.fileName.endsWith(".doc") || f.fileName.endsWith(".docx") || f.fileName.endsWith(".odt")) icon = "­ƒôÿ";

                                            return (
                                                <div className="schedule-file-item" key={f.id}>
                                                    <div className="schedule-file-info">
                                                        <span style={{fontSize: '1.6rem'}}>{icon}</span>
                                                        <div>
                                                            <div className="schedule-file-name" title={f.fileName}>{f.fileName}</div>
                                                            <div className="schedule-file-meta">{sizeMb} MB ÔÇó Subido el {new Date(f.timestamp).toLocaleDateString()}</div>
                                                        </div>
                                                    </div>
                                                    <div className="schedule-file-actions">
                                                        <button className="schedule-btn schedule-btn-secondary" onClick={() => handleDownload(f)}>­ƒôé Abrir</button>
                                                        <button className="schedule-btn schedule-btn-danger" onClick={() => handleDeleteFile(f.id)}>­ƒùæ´©Å Borrar</button>
                                                    </div>
                                                </div>
                                            );
                                        })
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Schedule;

