import React, { useState, useEffect } from 'react';
import { UserPlus, Search, Trash2, Edit2 } from 'lucide-react';
import BatchStudentModal from '../components/BatchStudentModal';
import StudentUpdateModal from '../components/StudentUpdateModal';
import api from '../api';

const Students = () => {
    const [estudiantes, setEstudiantes] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [showModal, setShowModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);
    const [selectedStudent, setSelectedStudent] = useState(null);
    const [config, setConfig] = useState(null);

    useEffect(() => {
        const configId = localStorage.getItem('activeConfigId');
        if (configId) {
            fetchStudents(configId);
            fetchConfig(configId);
        }
    }, []);

    const fetchConfig = (id) => {
        api.get(`/config?id=${id}`)
            .then(res => setConfig(res.data))
            .catch(err => console.error(err));
    };

    const fetchStudents = (id) => {
        api.get(`/estudiantes?configId=${id}`)
            .then(res => {
                const data = Array.isArray(res.data) ? res.data : [];
                setEstudiantes(data);
            })
            .catch(err => {
                console.error(err);
                setEstudiantes([]);
            });
    };

    const handleSaveBatch = (students) => {
        const configId = localStorage.getItem('activeConfigId');
        if (!configId) return alert('No hay un curso seleccionado.');

        return api.post('/estudiantes', { students, configId })
            .then(() => {
                // To avoid Pywebview/Electron deadlocks on modal unmount, we forcefully reset the view
                // since the user states "when they refresh, it works and shows filiaci├│n".
                window.location.reload();
            })
            .catch(err => {
                console.error('Error adding students:', err.response || err);
                const message = err.response?.data?.error || 'Error desconocido al agregar estudiantes';
                alert(message);
                throw err; // Re-throw to inform modal
            });
    };

    const handleDelete = (id) => {
        if (!window.confirm('┬┐Est├í seguro de eliminar este estudiante? Esta acci├│n no se puede deshacer.')) return;

        api.delete(`/estudiantes/${id}`)
            .then(() => {
                const configId = localStorage.getItem('activeConfigId');
                fetchStudents(configId);
                alert('Estudiante eliminado exitosamente');
            })
            .catch(err => {
                console.error('Error deleting student:', err);
                alert('Error al eliminar estudiante');
            });
    };

    const handleEditClick = (student) => {
        setSelectedStudent(student);
        setShowEditModal(true);
    };

    const handleUpdateStudent = (studentData) => {
        api.put(`/estudiantes/${studentData.id}`, studentData)
            .then(() => {
                const configId = localStorage.getItem('activeConfigId');
                fetchStudents(configId);
                setShowEditModal(false);
                alert('Estudiante actualizado exitosamente');
            })
            .catch(err => {
                console.error('Error updating student:', err);
                alert('Error al actualizar estudiante');
            });
    };

    const filtered = (Array.isArray(estudiantes) ? estudiantes : []).filter(e => {
        const search = searchTerm.toLowerCase();
        const apellidos = (e.apellidos || '').toLowerCase();
        const nombres = (e.nombres || '').toLowerCase();
        return apellidos.includes(search) || nombres.includes(search);
    });

    return (
        <div className="p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
                <div className="space-y-3 w-full md:w-auto">
                    <h2 className="text-3xl font-black text-slate-800 uppercase tracking-tight flex items-center gap-3">
                        <div className="w-2 h-10 bg-emerald-500 rounded-full"></div>
                        Registro de Filiaci├│n
                    </h2>

                    {config ? (
                        <div className="flex flex-wrap gap-4 text-[11px] font-bold uppercase tracking-wider">
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400">Maestro:</span>
                                <span className="text-slate-700">{config.maestro || '---'}</span>
                            </div>
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400">Grado:</span>
                                <span className="text-slate-700">{config.curso || '---'}</span>
                            </div>
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400">Nivel:</span>
                                <span className="text-slate-700">{config.nivel || '---'}</span>
                            </div>
                            <div className="bg-white px-3 py-1.5 rounded-lg border border-slate-200 shadow-sm flex items-center gap-2">
                                <span className="text-slate-400">Asignatura:</span>
                                <span className="text-slate-700">{config.area || '---'}</span>
                            </div>
                        </div>
                    ) : (
                        <div className="inline-flex bg-amber-50 text-amber-700 px-4 py-2 rounded-xl border border-amber-200 items-center gap-2 font-bold text-[11px] uppercase tracking-wider shadow-sm animate-pulse">
                            ÔÜá´©Å Debe seleccionar y guardar un curso en la Car├ítula para registrar estudiantes
                        </div>
                    )}
                </div>
                <button
                    onClick={() => setShowModal(true)}
                    className="bg-emerald-600 text-white px-6 py-3 rounded-2xl font-bold flex items-center space-x-2 hover:bg-emerald-700 transition shadow-lg shadow-emerald-200 hover:-translate-y-1 active:scale-95 whitespace-nowrap"
                >
                    <UserPlus size={20} />
                    <span>AGREGAR ESTUDIANTE</span>
                </button>
            </div>

            <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
                <div className="p-4 border-b border-slate-200 bg-slate-50 flex items-center px-6">
                    <Search className="text-slate-400 mr-3" size={18} />
                    <input
                        type="text"
                        placeholder="Buscar por apellidos o nombres..."
                        className="bg-transparent outline-none w-full text-sm py-1"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-[12px]">
                        <thead>
                            <tr className="bg-slate-900 text-white uppercase text-[10px] tracking-wider">
                                <th className="py-4 px-4 text-left">N┬║</th>
                                <th className="py-4 px-4 text-left">Apellidos y Nombres</th>
                                <th className="py-4 px-4 text-left">Nacimiento</th>
                                <th className="py-4 px-4 text-center">Edad</th>
                                <th className="py-4 px-4 text-left">RUDE</th>
                                <th className="py-4 px-4 text-left">C.I.</th>
                                <th className="py-4 px-4 text-left">Barrio/Calle</th>
                                <th className="py-4 px-4 text-left">Tutor / Padre</th>
                                <th className="py-4 px-4 text-center">Tel├®fono</th>
                                <th className="py-4 px-4 text-center"></th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                            {filtered.map((e, i) => {
                                // Super Safe Data Preparation
                                const apellidos = (e.apellidos || '').toUpperCase();
                                const nombres = (e.nombres || '').toUpperCase();
                                
                                let dateDisplay = '---';
                                if (e.fechaNacimiento) {
                                    try {
                                        const d = new Date(e.fechaNacimiento);
                                        if (!isNaN(d.getTime())) {
                                            // Force DD/MM/YYYY format manually for total control
                                            const day = String(d.getUTCDate()).padStart(2, '0');
                                            const month = String(d.getUTCMonth() + 1).padStart(2, '0');
                                            const year = d.getUTCFullYear();
                                            dateDisplay = `${day}/${month}/${year}`;
                                        }
                                    } catch (err) {
                                        dateDisplay = 'Error fecha';
                                    }
                                }

                                return (
                                    <tr key={e.id} className="hover:bg-blue-50/50 transition-colors">
                                        <td className="py-3 px-4 font-semibold text-slate-400">{i + 1}</td>
                                        <td className="py-3 px-4 font-bold text-slate-700 uppercase">
                                            {apellidos} {nombres}
                                        </td>
                                        <td className="py-3 px-4 text-slate-600">
                                            {dateDisplay}
                                        </td>
                                        <td className="py-3 px-4 text-center text-slate-600">{e.edad || '---'}</td>
                                        <td className="py-3 px-4 font-mono text-xs text-slate-500">{e.rude || '---'}</td>
                                        <td className="py-3 px-4 text-slate-500">{e.ci || '---'}</td>
                                        <td className="py-3 px-4 text-slate-600 text-[11px] max-w-[150px] truncate">{e.direccion || '---'}</td>
                                        <td className="py-3 px-4 text-slate-600 text-[11px] truncate">{e.padreMadre || '---'}</td>
                                        <td className="py-3 px-4 text-center text-slate-600 font-mono text-xs">{e.telefono || '---'}</td>
                                    <td className="py-3 px-4 text-center">
                                        <div className="flex items-center justify-center gap-1">
                                            <button 
                                                onClick={() => handleEditClick(e)}
                                                className="text-slate-300 hover:text-indigo-600 transition-colors p-2 rounded-lg hover:bg-indigo-50"
                                                title="Editar Estudiante"
                                            >
                                                <Edit2 size={16} />
                                            </button>
                                            <button 
                                                onClick={() => handleDelete(e.id)}
                                                className="text-slate-300 hover:text-red-500 transition-colors p-2 rounded-lg hover:bg-red-50"
                                                title="Eliminar Estudiante"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </div>
                                    </td>
                                    </tr>
                                );
                            })}
                            {filtered.length === 0 && (
                                <tr>
                                    <td colSpan="10" className="py-20 text-center text-slate-400 italic">No se encontraron estudiantes registrados.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            <BatchStudentModal 
                isOpen={showModal}
                onClose={() => setShowModal(false)}
                onSave={handleSaveBatch}
                existingStudents={estudiantes}
            />

            <StudentUpdateModal 
                isOpen={showEditModal}
                onClose={() => setShowEditModal(false)}
                student={selectedStudent}
                onSave={handleUpdateStudent}
            />
        </div>
    );
};

export default Students;
